function Eq($name,$actual,$expected){if($actual-ne$expected){Add-Error "$name expected=$expected actual=$actual"}}
function Seq($name,$actual,$expected){$a=if($null-eq$actual){@()}else{@($actual)};$e=if($null-eq$expected){@()}else{@($expected)};if(($a|ConvertTo-Json -Compress -Depth 20)-ne($e|ConvertTo-Json -Compress -Depth 20)){Add-Error "$name sequence mismatch"}}
