function Load($path){Get-Content -LiteralPath $path -Raw -Encoding UTF8|ConvertFrom-Json}
function Find-ExactSessionMessage($sourcePath,$expected){
 if($null-eq$global:Logh7AuthorityMessageCache){$global:Logh7AuthorityMessageCache=@{}}
 $cacheKey=([IO.Path]::GetFullPath($sourcePath)+'|'+[string]$expected.messageId+'|'+[string]$expected.rawLineSha256+'|'+[string]$expected.lineNumberOneBased)
 if($global:Logh7AuthorityMessageCache.ContainsKey($cacheKey)){return $global:Logh7AuthorityMessageCache[$cacheKey]}
 $utf8=[Text.UTF8Encoding]::new($false);$stream=$null;$reader=$null;$lineNumber=0;$matches=@()
 try{
  $stream=[IO.FileStream]::new($sourcePath,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::ReadWrite)
