  while(($line=$reader.ReadLine())-ne$null){
   $lineNumber++;if(-not$line.Contains([string]$expected.messageId)){continue}
   try{$item=$line|ConvertFrom-Json}catch{continue}
   if($item.type-ne'response_item'-or$item.payload.type-ne'message'-or$item.payload.id-ne$expected.messageId){continue}
   $matches+=,[ordered]@{lineNumber=$lineNumber;item=$item;rawLineSha256=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($utf8.GetBytes($line)))}
  }
 }finally{if($null-ne$reader){$reader.Dispose()}elseif($null-ne$stream){$stream.Dispose()}}
